function sFault(id){
  const F=window.SURF&&window.SURF.api&&window.SURF.api.fault; if(!F)return false;
  const k=String(id).toUpperCase().replace('M-01','M01');
  if(k==='M01')return !!F.central;
  const m=/^S([1-4])$/.exec(k);
  return m?!!F.s[parseInt(m[1],10)-1]:false;
}
function sAlarm(id){
  const A=window.SURF&&window.SURF.api&&window.SURF.api.alarm; if(!A)return 0;
  const k=String(id).toUpperCase().replace('M-01','M01');
  if(k==='M01')return A.central||0;
  const m=/^S([1-4])$/.exec(k);
  return m?(A.s[parseInt(m[1],10)-1]||0):0;
}
